package com.stockmarketanalyzer.backend.common;

import jakarta.persistence.Column;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import java.util.Objects;
import lombok.Getter;
import lombok.ToString;
import org.hibernate.proxy.HibernateProxy;

/**
 * The surrogate primary key every entity carries, and the one equality rule they all share.
 *
 * <p>Equality is by primary key, written here once rather than generated by Lombok: a
 * field-wide {@code @EqualsAndHashCode} breaks Hibernate's identity guarantees for lazy proxies
 * and detached instances. The rules:
 *
 * <ul>
 *   <li>Two instances are equal when they are the same persistent class and share a non-null id.
 *       A transient entity (no id yet) equals only itself.
 *   <li>The class is resolved through {@link HibernateProxy} so an uninitialised lazy proxy
 *       compares equal to the real instance -- without being initialised to find out.
 *   <li>The id is read through {@link #getId()}, never the field: on a proxy the field is
 *       always {@code null}, whereas the getter is answered from the proxy's identifier.
 *   <li>The hash code is constant per class, so it cannot change when {@code persist()} assigns
 *       the id while the entity is sitting in a {@code HashSet}.
 * </ul>
 *
 * <p>Both methods are {@code final} so no subclass can quietly reintroduce field-based equality.
 */
@Getter
@MappedSuperclass
@ToString(onlyExplicitlyIncluded = true)
public abstract class BaseEntity {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    @ToString.Include
    private Long id;

    @Override
    public final boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof BaseEntity entity) || persistentClass(this) != persistentClass(other)) {
            return false;
        }
        return getId() != null && Objects.equals(getId(), entity.getId());
    }

    @Override
    public final int hashCode() {
        return persistentClass(this).hashCode();
    }

    private static Class<?> persistentClass(Object entity) {
        return entity instanceof HibernateProxy proxy
                ? proxy.getHibernateLazyInitializer().getPersistentClass()
                : entity.getClass();
    }
}
